const body = $json.body ?? $json;
const pedido_id = body.pedido_id || body.orderId;
const pizzaria_id = body.pizzaria_id || body.pizzeriaId;
if (!pedido_id || !pizzaria_id) {
  throw new Error('pedido_id e pizzaria_id s?o obrigat?rios');
}
return [{ json: { pedido_id, pizzaria_id, telefone: body.telefone || body.customerPhone || '', instancia: body.instancia || body.instance || '' } }];

// Normaliza retorno dos dois gateways em formato unico
// Tenta obter dados do pedido - pode nao existir se p04 falhou
let pedido = {};
try { pedido = $('Carregar Pedido').first().json; } catch(e) {}
const resp = $json;

// Se $json tem 'error' key ou nao tem 'id', a chamada falhou
let paymentId = '', paymentLink = '', pixCopiaCola = '';
if (resp && resp.id && resp.invoiceUrl) {
  // Asaas
  paymentId = String(resp.id);
  paymentLink = resp.invoiceUrl;
  pixCopiaCola = resp.encodedImage || '';
} else if (resp && resp.id && resp.point_of_interaction) {
  // MercadoPago
  paymentId = String(resp.id);
  paymentLink = resp.point_of_interaction?.transaction_data?.ticket_url || '';
  pixCopiaCola = resp.point_of_interaction?.transaction_data?.qr_code || '';
}

const hasLink = !!(paymentLink && paymentLink.length > 0);

return [{
  json: {
    ok: hasLink,
    error: hasLink ? null : 'Gateway de pagamento nao configurado ou credencial invalida.',
    pedido_id: pedido.id || '',
    pizzaria_id: pedido.pizzaria_id || '',
    telefone: pedido.cliente_telefone || '',
    instancia: pedido.instancia || '',
    payment_id: paymentId,
    payment_link: paymentLink,
    pix_copia_cola: pixCopiaCola,
    numero_pedido: pedido.numero_pedido || '',
    valor_total: pedido.valor_total || 0
  }
}];

