// Aceita formatos de Asaas e MercadoPago
const body = $json.body ?? $json;
let pedidoExternalRef = '', status = '', paymentId = '';

if (body.event && body.payment) {
  // Asaas: { event: 'PAYMENT_RECEIVED', payment: { id, status, externalReference, value } }
  paymentId = String(body.payment.id || '');
  pedidoExternalRef = String(body.payment.externalReference || '');
  const evt = String(body.event).toUpperCase();
  if (evt.includes('RECEIVED') || evt.includes('CONFIRMED')) status = 'approved';
  else if (evt.includes('REFUND') || evt.includes('DELETED') || evt.includes('CANCELED')) status = 'cancelled';
  else status = 'pending';
} else if (body.action || body.type) {
  // MercadoPago: { action, data: { id }, type: 'payment' }
  paymentId = String(body.data?.id || body.resource || '');
  // Para MP precisamos do externalReference no payload completo (alguns webhooks j? enviam, outros n?o)
  pedidoExternalRef = String(body.external_reference || body.data?.external_reference || '');
  status = body.action === 'payment.updated' ? 'approved' : 'pending';
}

return [{
  json: {
    skip: !pedidoExternalRef && !paymentId,
    pedido_id: pedidoExternalRef,
    payment_id: paymentId,
    payment_status: status
  }
}];

